"""Classic and averaged perceptron, plus linearly separable Gaussian demo data."""

import numpy as np


def make_clouds(n_per_class=300, centers=((-2.0, -2.0), (2.0, 2.0)), std=0.5, seed=9):
    """Two Gaussian clouds, labels -1 / +1."""
    rng = np.random.default_rng(seed)
    X_parts, y_parts = [], []
    for label, c in zip((-1, 1), centers):
        X_parts.append(rng.normal(loc=c, scale=std, size=(n_per_class, len(c))))
        y_parts.append(np.full(n_per_class, label))
    return np.vstack(X_parts), np.concatenate(y_parts)


def _augment(X):
    """Append bias column."""
    return np.hstack([X, np.ones((X.shape[0], 1))])


def fit_perceptron(X, y, epochs=20, seed=0):
    """Classic perceptron. Returns (w, mistakes_per_epoch)."""
    Xa, w, rng = _augment(X), np.zeros(X.shape[1] + 1), np.random.default_rng(seed)
    mistakes = []
    for _ in range(epochs):
        n_wrong = 0
        for i in rng.permutation(len(y)):
            if y[i] * (Xa[i] @ w) <= 0:
                w += y[i] * Xa[i]
                n_wrong += 1
        mistakes.append(n_wrong)
        if n_wrong == 0:
            break
    return w, mistakes


def fit_averaged_perceptron(X, y, epochs=20, seed=0):
    """Averaged perceptron (average of w over all update steps). Returns w_avg."""
    Xa, w, rng = _augment(X), np.zeros(X.shape[1] + 1), np.random.default_rng(seed)
    w_sum = np.zeros_like(w)
    steps = 0
    done = False
    for _ in range(epochs):
        n_wrong = 0
        for i in rng.permutation(len(y)):
            if y[i] * (Xa[i] @ w) <= 0:
                w += y[i] * Xa[i]
                n_wrong += 1
            w_sum += w
            steps += 1
        if n_wrong == 0:
            break
    return w_sum / steps


def predict(w, X):
    return np.where(_augment(X) @ w >= 0, 1, -1)


def accuracy(w, X, y):
    return float(np.mean(predict(w, X) == y))

